target.css:
:root {
  --ink: #202a3a;
  --muted: #718095;
  --paper: #ffffff;
  --line: #d9e1e9;
  --navy: #233f68;
  --blue: #3e7bc6;
  --aqua: #57c4bb;
  --aqua-pale: #e2f6f2;
  --amber: #eaa54b;
  --amber-pale: #fff2dc;
}

* {
  box-sizing: border-box;
}

.panel {
  width: 492px;
  padding: 10px;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-top: 4px solid var(--navy);
  border-radius: 14px;
}

.panel-header {
  display: flex;
  align-items: center;
  gap: 8px;
}

.mark {
  display: grid;
  width: 29px;
  height: 29px;
  place-items: center;
  color: var(--paper);
  background: var(--navy);
  border-radius: 8px;
  font-size: 21px;
  font-weight: 700;
  line-height: 1;
}

.title-block {
  flex: 1;
}

.title-block h1 {
  margin: 0;
  font-size: 16px;
  font-weight: 750;
  line-height: 1.05;
  letter-spacing: -0.3px;
}

.title-block p {
  margin: 2px 0 0;
  color: var(--muted);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.42px;
}

.live {
  padding: 4px 7px;
  color: var(--navy);
  background: var(--aqua-pale);
  border-radius: 999px;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.6px;
}

.tabs {
  display: flex;
  gap: 3px;
  margin: 9px 0 8px;
  padding: 3px;
  background: var(--aqua-pale);
  border-radius: 8px;
}

.tabs button {
  flex: 1;
  padding: 5px 7px;
  color: var(--muted);
  background: var(--aqua-pale);
  border: 0;
  border-radius: 5px;
  font-size: 11px;
  font-weight: 700;
  line-height: 1;
}

.tabs button.active {
  color: var(--paper);
  background: var(--navy);
}

.content {
  display: grid;
  grid-template-columns: 3fr 2fr;
  gap: 8px;
}

.trace-card {
  padding: 9px;
  background: var(--navy);
  border-radius: 10px;
}

.card-heading {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  color: var(--paper);
}

.card-heading h2 {
  margin: 0;
  font-size: 12px;
  font-weight: 750;
}

.card-heading span {
  color: var(--aqua);
  font-size: 9px;
  font-weight: 700;
}

.calibration {
  display: flex;
  height: 40px;
  align-items: center;
  gap: 4px;
  margin: 7px 0 4px;
  border-top: 1px solid var(--blue);
  border-bottom: 1px solid var(--blue);
}

.calibration span {
  flex: 1;
  height: 6px;
  background: var(--aqua);
  border-radius: 999px;
}

.calibration span:nth-child(2) { height: 13px; }
.calibration span:nth-child(3) { height: 8px; }
.calibration span:nth-child(4) { height: 25px; background: var(--amber); }
.calibration span:nth-child(5) { height: 11px; }
.calibration span:nth-child(6) { height: 18px; }
.calibration span:nth-child(7) { height: 7px; }
.calibration span:nth-child(8) { height: 13px; }
.calibration span:nth-child(9) { height: 6px; }

.trace-note {
  margin: 0;
  color: var(--aqua-pale);
  font-size: 9px;
  line-height: 1.15;
}

.readings {
  display: grid;
  gap: 5px;
}

.reading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 6px 8px;
  border: 1px solid var(--line);
  border-radius: 8px;
}

.reading span {
  color: var(--muted);
  font-size: 9px;
  font-weight: 650;
}

.reading strong {
  color: var(--navy);
  font-size: 13px;
  line-height: 1;
}

.reading small {
  color: var(--blue);
  font-size: 8px;
}

.alert {
  display: flex;
  grid-column: 1 / -1;
  align-items: center;
  gap: 7px;
  padding: 7px 9px;
  background: var(--amber-pale);
  border: 1px solid var(--amber);
  border-radius: 8px;
}

.alert-icon {
  display: grid;
  width: 17px;
  height: 17px;
  place-items: center;
  color: var(--paper);
  background: var(--amber);
  border-radius: 50%;
  font-size: 11px;
  font-weight: 800;
}

.alert h3 {
  margin: 0;
  color: var(--navy);
  font-size: 10px;
  line-height: 1.1;
}

.alert p {
  margin: 1px 0 0;
  color: var(--muted);
  font-size: 9px;
  line-height: 1.15;
}

.panel-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 8px;
}

.panel-footer p {
  margin: 0;
  color: var(--muted);
  font-size: 9px;
}

.export {
  padding: 6px 9px;
  color: var(--paper);
  background: var(--blue);
  border: 0;
  border-radius: 6px;
  font-size: 10px;
  font-weight: 750;
  line-height: 1;
}

